// GENERATED from the ffmpeg-verified Python reference implementation (proto/rtp.py).
// `cargo test` checks that the Rust port produces byte-identical output.
use crate::{jpeg, rtp};

pub(crate) fn hex(s: &str) -> Vec<u8> {
    (0..s.len() / 2).map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap()).collect()
}

pub(crate) const JPEG_HEX: &str = "";

#[test]
fn jpeg_analysis_matches_reference() {
    let d = hex(JPEG_HEX);
    let i = jpeg::analyze(&d).unwrap();
    assert_eq!((i.width, i.height, i.rtp_type, i.dri), (64, 48, 0, 0));
    assert_eq!((i.scan_start, i.scan_end), (623, 3064));
    assert_eq!(i.qtables, hex("080606070605080707070909080a0c140d0c0b0b0c1912130f141d1a1f1e1d1a1c1c20242e2720222c231c1c2837292c30313434341f27393d38323c2e3334320909090c0b0c180d0d1832211c213232323232323232323232323232323232323232323232323232323232323232323232323232323232323232323232323232"));
    assert!(!i.custom_huffman);
}

#[test]
fn jpeg_packets_match_reference() {
    let d = hex(JPEG_HEX);
    let i = jpeg::analyze(&d).unwrap();
    let mut seq: u16 = 0xFFFE;
    let got = rtp::packetize_jpeg(&i, &d, 0x11223344, 0xAABBCCDD, &mut seq, 400);
    let want: Vec<Vec<u8>> = vec![hex(""), hex(""), hex(""), hex(""), hex(""), hex(""), hex("")];
    assert_eq!(got.len(), want.len());
    for (n, (g, w)) in got.iter().zip(want.iter()).enumerate() { assert_eq!(g, w, "packet {}", n); }
    assert_eq!(seq, 0x0005);
}

#[test]
fn l16_packets_match_reference() {
    let mut seq: u16 = 7;
    let pcm = hex("0201feffff7f008010203040");
    let got = rtp::packetize_l16(&pcm, 1, 1000, 940, 0x01020304, 0xCAFEBABE, &mut seq, 8);
    let want: Vec<Vec<u8>> = vec![hex("8061000701020340cafebabe0102fffe7fff8000"), hex("8061000801020344cafebabe20104030")];
    assert_eq!(got, want);
    assert_eq!(seq, 9);
}

#[test]
fn l16_stereo_packets_match_reference() {
    let mut seq: u16 = 0;
    let pcm = hex("000102030405060708090a0b0c0d0e0f");
    let got = rtp::packetize_l16(&pcm, 2, 0, 0, 0, 0x01, &mut seq, 8);
    let want: Vec<Vec<u8>> = vec![hex("8061000000000000000000010100030205040706"), hex("80610001000000020000000109080b0a0d0c0f0e")];
    assert_eq!(got, want);
}

#[test]
fn sender_report_matches_reference() {
    let got = rtp::sender_report(0x0A0B0C0D, 1_700_000_000_123_456, 0x00112233, 42, 4200, "uvcweb");
    assert_eq!(got, hex("80c800060a0b0c0de8fe6f801f9acffa001122330000002a0000106881ca00040a0b0c0d010675766377656200000000"));
}
